import React, { useState } from 'react';

function MegaboxGuide() {
  // 메가박스 안내 특별관 리스트 데이터
  const guideList = [
    {
      id: 1,
      title: "Dolby Cinema",
      badge: "",
      // 👉 [주석] Dolby Cinema 이미지 경로
      image: "" 
    },
    {
      id: 2,
      title: "Dolby Vision Atmos",
      badge: "NEW",
      // 👉 [주석] Dolby Vision Atmos 이미지 경로
      image: "" 
    },
    {
      id: 3,
      title: "Mega MX4D",
      badge: "",
      // 👉 [주석] Mega MX4D 이미지 경로
      image: "" 
    },
    {
      id: 4,
      title: "Mega Dolby Atmos",
      badge: "",
      // 👉 [주석] Mega Dolby Atmos 이미지 경로
      image: "" 
    },
    {
      id: 5,
      title: "Mega LED",
      badge: "NEW",
      // 👉 [주석] Mega LED 이미지 경로
      image: "" 
    },
    {
      id: 6,
      title: "Boutique Private",
      badge: "",
      // 👉 [주석] Boutique Private 이미지 경로
      image: "" 
    }
  ];

  return (
    <section className="w-full bg-[#fbfbfa] pt-16 pb-16 flex flex-col items-center relative overflow-hidden">
      
      <div className="w-full max-w-6xl px-6">
        
        {/* 상단 타이틀 */}
        <div className="mb-8">
          <h2 className="text-2xl font-black text-zinc-900 tracking-tight">메가박스 안내</h2>
        </div>

        {/* 안내 카드 슬라이더/그리드 영역 */}
        <div className="relative flex items-center">
          
          {/* 좌측 슬라이드 화살표 버튼 */}
          <button className="absolute -left-5 z-10 w-10 h-10 rounded-full bg-white shadow-md border border-zinc-200 flex items-center justify-center text-zinc-400 hover:text-zinc-800 transition">
            &lt;
          </button>

          {/* 카드 목록 컨테이너 */}
          <div className="w-full grid grid-cols-2 md:grid-cols-6 gap-4">
            {guideList.map((item) => (
              <div 
                key={item.id} 
                className="group relative h-48 rounded-2xl overflow-hidden shadow-lg bg-zinc-900 cursor-pointer border border-zinc-800 flex flex-col justify-end p-4 transition-all duration-300"
              >
                {/* 💡 [주석: 안내 카드 이미지 영역] 
                  기본 상태: grayscale (흑백 / 색상 없음)
                  호버 상태: group-hover:grayscale-0 (컬러 원본 색상 복원)
                */}
                <div className="absolute inset-0 w-full h-full bg-zinc-800 flex items-center justify-center">
                  {item.image ? (
                    <img 
                      src={item.image} 
                      alt={item.title} 
                      className="w-full h-full object-cover grayscale group-hover:grayscale-0 group-hover:scale-105 transition-all duration-500" 
                    />
                  ) : (
                    <div className="text-center p-2">
                      <span className="text-[10px] text-zinc-500 block">특별관 이미지</span>
                    </div>
                  )}
                </div>

                {/* 어두운 그라데이션 오버레이 (텍스트 가독성 확보) */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent pointer-events-none"></div>

                {/* 우측 상단 NEW 뱃지 (있는 경우에만 표시) */}
                {item.badge && (
                  <span className="absolute top-3 right-3 bg-[#00a086] text-white text-[9px] font-bold px-2 py-0.5 rounded shadow z-10">
                    {item.badge}
                  </span>
                )}

                {/* 하단 타이틀 텍스트 */}
                <div className="relative z-10">
                  <h4 className="text-xs font-bold text-white tracking-wide group-hover:text-purple-300 transition-colors">
                    {item.title}
                  </h4>
                </div>

              </div>
            ))}
          </div>

          {/* 우측 슬라이드 화살표 버튼 */}
          <button className="absolute -right-5 z-10 w-10 h-10 rounded-full bg-white shadow-md border border-zinc-200 flex items-center justify-center text-zinc-400 hover:text-zinc-800 transition">
            &gt;
          </button>

        </div>

      </div>

    </section>
  );
}

export default MegaboxGuide;
